using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;

namespace FracturedVow.EditorTools
{
    /// <summary>
    /// Tools > Fractured Vow > Build Level: Floor 1 (The Warden's Pit)
    /// Builds the draft geometry for Floor 1 with generated stone, brick, wood and water textures,
    /// torches, props, static placeholders for items and enemies, numbered tour signs and the player.
    /// Everything is free: textures are generated by this script, no downloads needed.
    /// Put this file in your project's Editor folder (next to MilestoneSceneBuilder.cs).
    /// </summary>
    public class Floor1LevelBuilder : EditorWindow
    {
        GameObject playerPrefab;
        bool ceilings = true;
        bool tourSigns = true;
        string report = "";

        string root, genDir, texDir, matDir, meshDir, scenePath;
        Mesh unitCube;
        readonly Dictionary<string, Mesh> meshCache = new Dictionary<string, Mesh>();
        System.Random rng;

        Material mWall, mMossWall, mFloor, mRubble, mWood, mWater, mMetal, mPillar;
        Material mEnemy, mBoss, mPowerUp, mTool, mTrap, mInteract, mBoat, mFlame, mBone;

        Transform gStructure, gCeilings, gProps, gLights, gItems, gEnemies, gTraps, gInteract, gTour;

        [MenuItem("Tools/Fractured Vow/Build Level: Floor 1 (The Warden's Pit)")]
        static void Open()
        {
            var w = GetWindow<Floor1LevelBuilder>("Floor 1 Builder");
            w.minSize = new Vector2(360, 300);
        }

        /// <summary>Player (Hero) if Set Up Imported Packs has made it, otherwise Player (Knight).</summary>
        static GameObject DefaultPlayer()
        {
            foreach (var n in new[] { "Player (Hero)", "Player (Knight)" })
                foreach (var guid in AssetDatabase.FindAssets(n + " t:Prefab"))
                {
                    var go = AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(guid));
                    if (go != null && go.name == n) return go;
                }
            return null;
        }

        void OnGUI()
        {
            EditorGUILayout.LabelField("Floor 1 - The Warden's Pit (level draft)", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "1. Open CharacterControlTest, drag 'Player (Knight)' from the Hierarchy into the Project window to make a prefab.\n" +
                "2. Drag that prefab into the slot below.\n" +
                "3. Click Build. The scene is saved to <your folder>/Scenes/Floor1_WardensPit.unity.",
                MessageType.Info);
            if (playerPrefab == null) playerPrefab = DefaultPlayer();
            playerPrefab = (GameObject)EditorGUILayout.ObjectField("Player prefab", playerPrefab, typeof(GameObject), false);
            ceilings = EditorGUILayout.Toggle("Build ceilings", ceilings);
            tourSigns = EditorGUILayout.Toggle("Numbered tour signs", tourSigns);
            EditorGUILayout.Space();
            if (GUILayout.Button("Build Floor 1", GUILayout.Height(36))) EditorApplication.delayCall += Build;
            if (!string.IsNullOrEmpty(report)) EditorGUILayout.HelpBox(report, MessageType.None);
        }

        // =====================================================================================
        // BUILD
        // =====================================================================================

        void Build()
        {
            if (EditorApplication.isPlaying) { report = "Exit Play mode first."; Repaint(); return; }
            if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()) return;

            ResolvePaths();
            rng = new System.Random(7);
            meshCache.Clear();

            var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);
            MakeMaterials();

            var temp = GameObject.CreatePrimitive(PrimitiveType.Cube);
            unitCube = temp.GetComponent<MeshFilter>().sharedMesh;
            DestroyImmediate(temp);

            var level = new GameObject("Floor 1 - The Wardens Pit").transform;
            gStructure = Group("Structure", level);
            gCeilings = Group("Ceilings (hide for top-down screenshots)", level);
            gProps = Group("Props", level);
            gLights = Group("Torches", level);
            gItems = Group("Items (placeholders)", level);
            gEnemies = Group("Enemies (static placeholders)", level);
            gTraps = Group("Traps (placeholders)", level);
            gInteract = Group("Interactables (placeholders)", level);
            gTour = Group("Tour Signs", level);

            SetupLighting();
            BuildCellBlock();
            BuildGuardRoomAndArmory();
            BuildCatacombs();
            BuildCollapsedHall();
            BuildCistern();
            BuildAscentAndGallery();
            BuildWardensPit();
            BuildExit();

            gCeilings.gameObject.SetActive(ceilings);
            gTour.gameObject.SetActive(tourSigns);

            PlacePlayerAndCamera(new Vector3(-4f, 0.05f, 3f), Quaternion.Euler(0f, 90f, 0f));

            var systems = new GameObject("Systems").transform;
            new GameObject("GameManager").AddComponent<GameManager>().transform.SetParent(systems);
            var hud = new GameObject("PrototypeHUD").AddComponent<PrototypeHUD>();
            hud.showControls = false;
            hud.transform.SetParent(systems);

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, scenePath);
            AddToBuildSettings(scenePath);
            AssetDatabase.SaveAssets();

            report = "Built and saved " + scenePath +
                     (playerPrefab == null ? "\nNo player prefab assigned: a white spawn marker was placed instead." : "") +
                     "\nCheck the new Levels/Floor1 folder and the scene into Unity Version Control.";
            Debug.Log("[Fractured Vow] " + report);
            Repaint();
        }

        void ResolvePaths()
        {
            string me = AssetDatabase.GetAssetPath(MonoScript.FromScriptableObject(this)).Replace('\\', '/');
            string editorDir = me.Substring(0, me.LastIndexOf('/'));
            root = editorDir.EndsWith("/Editor") ? editorDir.Substring(0, editorDir.LastIndexOf('/')) : "Assets/FracturedVow";
            genDir = root + "/Levels/Floor1";
            texDir = genDir + "/Textures";
            matDir = genDir + "/Materials";
            meshDir = genDir + "/Meshes";
            scenePath = root + "/Scenes/Floor1_WardensPit.unity";
            EnsureFolder(texDir); EnsureFolder(matDir); EnsureFolder(meshDir); EnsureFolder(root + "/Scenes");
        }

        void SetupLighting()
        {
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.16f, 0.16f, 0.2f);
            RenderSettings.fog = true;
            RenderSettings.fogMode = FogMode.ExponentialSquared;
            RenderSettings.fogColor = new Color(0.05f, 0.05f, 0.07f);
            RenderSettings.fogDensity = 0.018f;
            var sun = Object.FindFirstObjectByType<Light>();
            if (sun != null)
            {
                sun.name = "Moonlight (dim)";
                sun.intensity = 0.25f;
                sun.color = new Color(0.6f, 0.7f, 1f);
                sun.transform.rotation = Quaternion.Euler(65f, 30f, 0f);
            }
            if (Camera.main != null)
            {
                Camera.main.clearFlags = CameraClearFlags.SolidColor;
                Camera.main.backgroundColor = new Color(0.03f, 0.03f, 0.05f);
            }
        }

        // =====================================================================================
        // AREAS  (x = east, z = north, y = up; 1 unit = 1 m)
        // =====================================================================================

        // 1. Cell Block: x -6..6, z 0..20. Player wakes in the south-west cell.
        void BuildCellBlock()
        {
            var a = Group("1 Cell Block", gStructure);
            Floor(a, -6, 6, 0, 20, 0f, mFloor);
            WallX(a, 0f, -6, 6, 0, 4.5f, mMossWall);
            WallX(a, 20f, -6, 6, 0, 4.5f, mWall, new Vector2(0.5f, 3.5f));
            WallZ(a, -6f, 0, 20, 0, 4.5f, mMossWall);
            WallZ(a, 6f, 0, 20, 0, 4.5f, mWall);
            Ceiling(-6, 6, 0, 20, 4.5f);

            // west cells (z 0-6, 6-12, 12-18) and east cells (z 0-6, 6-12)
            foreach (float z in new[] { 6f, 12f, 18f }) Box("Cell Divider", a, new Vector3(-4f, 2.25f, z), new Vector3(4f, 4.5f, 0.3f), mWall);
            foreach (float z in new[] { 6f, 12f }) Box("Cell Divider", a, new Vector3(4.5f, 2.25f, z), new Vector3(3f, 4.5f, 0.3f), mWall);
            Bars(a, -2f, 0f, 6f, new Vector2(2f, 3.6f)); // start cell, bars bent open
            Bars(a, -2f, 6f, 12f, null);
            Bars(a, -2f, 12f, 18f, null);
            Bars(a, 3f, 0f, 6f, null);
            Bars(a, 3f, 6f, 12f, null);

            Bones(new Vector3(-4.5f, 0f, 9f)); Bones(new Vector3(4.6f, 0f, 3f)); Bones(new Vector3(-4f, 0f, 15f));
            Chains(new Vector3(-5.8f, 2.8f, 2f)); Chains(new Vector3(-5.8f, 2.8f, 4f));
            Box("Straw Bed", gProps, new Vector3(-5f, 0.15f, 4.5f), new Vector3(1.6f, 0.3f, 1f), mWood);
            Barrel(new Vector3(5f, 0f, 18.5f)); Barrel(new Vector3(4.2f, 0f, 19f)); Crate(new Vector3(-5f, 0f, 19f), 1f);

            Torch(new Vector3(0.5f, 2.6f, 0.3f), 0f); Torch(new Vector3(-1.5f, 2.6f, 19.7f), 180f); Torch(new Vector3(5.7f, 2.6f, 15f), 270f);

            Item("Health Potion", PrimitiveType.Sphere, new Vector3(0f, 0.5f, 15f), Vector3.one * 0.45f, mPowerUp);
            Enemy("Husk (sleeping in cell)", new Vector3(-4f, 0f, 9f), 90f, false);
            Sign("1  CELL BLOCK", new Vector3(0f, 3.4f, 4f));

            // corridor to the guard room: x 0.5..3.5, z 20..26
            var c = Group("Corridor", gStructure);
            Floor(c, 0.5f, 3.5f, 20, 26, 0f, mFloor);
            WallZ(c, 0.5f, 20, 26, 0, 4f, mWall);
            WallZ(c, 3.5f, 20, 26, 0, 4f, mWall);
            Ceiling(0.5f, 3.5f, 20, 26, 4f);
        }

        // 2b. Lower Catacombs: an optional 12-room wing west of the guard room (x -100..-17, z 3..61).
        //     The first room is a safe den with the merchant and a sellsword; the rest is a maze of
        //     skeletons, necromancers and ghouls with chests in its dead ends.
        void BuildCatacombs()
        {
            const int cols = 4, rows = 3;
            const float P = 22f;
            var rnd = new System.Random(31);
            float X(int c) => -24f - c * P;
            float Z(int r) => 10f + r * P;
            var size = new float[cols, rows];
            for (int c = 0; c < cols; c++) for (int r = 0; r < rows; r++) size[c, r] = (c == 0 && r == 1) ? 14f : 12f + rnd.Next(0, 3) * 2f;

            // a random spanning tree over the grid, plus a few loops
            var links = new List<(int, int, int, int)>();
            var parent = new int[cols * rows];
            for (int i = 0; i < parent.Length; i++) parent[i] = i;
            int Find(int x) { while (parent[x] != x) x = parent[x] = parent[parent[x]]; return x; }
            var edges = new List<(int, int, int, int)>();
            for (int c = 0; c < cols; c++) for (int r = 0; r < rows; r++)
            {
                if (c + 1 < cols) edges.Add((c, r, c + 1, r));
                if (r + 1 < rows) edges.Add((c, r, c, r + 1));
            }
            for (int i = edges.Count - 1; i > 0; i--) { int j = rnd.Next(i + 1); var t = edges[i]; edges[i] = edges[j]; edges[j] = t; }
            int loops = 0;
            foreach (var e in edges)
            {
                int a = Find(e.Item1 * rows + e.Item2), b = Find(e.Item3 * rows + e.Item4);
                if (a != b) { parent[a] = b; links.Add(e); }
                else if (loops < 3) { links.Add(e); loops++; }
            }
            var degree = new int[cols, rows];
            foreach (var l in links) { degree[l.Item1, l.Item2]++; degree[l.Item3, l.Item4]++; }

            // gaps for every link
            var gapN = new List<Vector2>[cols, rows]; var gapS = new List<Vector2>[cols, rows];
            var gapE = new List<Vector2>[cols, rows]; var gapW = new List<Vector2>[cols, rows];
            for (int c = 0; c < cols; c++) for (int r = 0; r < rows; r++) { gapN[c, r] = new List<Vector2>(); gapS[c, r] = new List<Vector2>(); gapE[c, r] = new List<Vector2>(); gapW[c, r] = new List<Vector2>(); }
            gapE[0, 1].Add(new Vector2(31f, 34f)); // to the guard room
            foreach (var l in links)
            {
                if (l.Item2 == l.Item4) { float z = Z(l.Item2); var g = new Vector2(z - 1.5f, z + 1.5f); gapW[l.Item1, l.Item2].Add(g); gapE[l.Item3, l.Item4].Add(g); } // columns run west (x decreases)
                else { float x = X(l.Item1); var g = new Vector2(x - 1.5f, x + 1.5f); gapN[l.Item1, l.Item2].Add(g); gapS[l.Item3, l.Item4].Add(g); }
            }

            string[] names = { "Smuggler's Den", "Bone Pit", "Weeping Crypt", "Forgotten Ossuary", "Rat Warrens", "Sunken Chapel", "Charnel Vault", "Gravekeeper's Rest", "Hall of Skulls", "Silent Tomb", "Ash Sepulchre", "Deep Catacomb" };
            int nameIdx = 0, deadEnds = 0;
            for (int c = 0; c < cols; c++) for (int r = 0; r < rows; r++)
            {
                float x = X(c), z = Z(r), s = size[c, r], hs = s / 2f;
                var g = Group("Catacombs " + c + "," + r, gStructure);
                Floor(g, x - hs, x + hs, z - hs, z + hs, 0f, mFloor);
                WallX(g, z - hs, x - hs, x + hs, 0, 5f, mMossWall, gapS[c, r].ToArray());
                WallX(g, z + hs, x - hs, x + hs, 0, 5f, mMossWall, gapN[c, r].ToArray());
                WallZ(g, x - hs, z - hs, z + hs, 0, 5f, mMossWall, gapW[c, r].ToArray());
                WallZ(g, x + hs, z - hs, z + hs, 0, 5f, mMossWall, gapE[c, r].ToArray());
                Ceiling(x - hs, x + hs, z - hs, z + hs, 5f);
                Torch(new Vector3(x - hs * 0.5f, 2.6f, z - hs + 0.3f), 0f);
                Torch(new Vector3(x + hs * 0.5f, 2.6f, z + hs - 0.3f), 180f);
                string name = c == 0 && r == 1 ? names[0] : names[1 + (nameIdx++ % (names.Length - 1))];
                Sign(name.ToUpperInvariant(), new Vector3(x, 3.6f, z));
                Bones(new Vector3(x - hs + 1.2f, 0f, z + hs - 1.2f));
                if (rnd.NextDouble() < 0.6) Barrel(new Vector3(x + hs - 1f, 0f, z - hs + 1f));
                if (rnd.NextDouble() < 0.5) Crate(new Vector3(x - hs + 1f, 0f, z - hs + 1f), 0.9f);
                Chains(new Vector3(x + hs - 0.2f, 3f, z));

                if (c == 0 && r == 1)
                {
                    // safe den: merchant and a sellsword by the fire
                    Interact("Merchant", PrimitiveType.Capsule, new Vector3(x - 3f, 1f, z + 4f), new Vector3(0.6f, 1f, 0.6f), false);
                    Interact("Mercenary: Bram the Sellsword", PrimitiveType.Capsule, new Vector3(x + 3f, 1f, z + 4f), new Vector3(0.6f, 1f, 0.6f), false);
                    Box("Campfire Stones", gProps, new Vector3(x, 0.1f, z), new Vector3(1.4f, 0.2f, 1.4f), mRubble);
                    Torch(new Vector3(x, 0.6f, z), 0f);
                    Item("Health Potion", PrimitiveType.Sphere, new Vector3(x + 4f, 0.5f, z - 4f), Vector3.one * 0.45f, mPowerUp);
                    continue;
                }
                bool dead = degree[c, r] == 1;
                int depth = c + Mathf.Abs(r - 1);
                int mobs = Mathf.Clamp(1 + depth / 2 + (dead ? 1 : 0), 1, 4);
                for (int i = 0; i < mobs; i++)
                {
                    double roll = rnd.NextDouble();
                    string kind = roll < 0.55 ? "Catacomb Skeleton" : roll < 0.8 ? "Catacomb Necromancer" : "Catacomb Ghoul";
                    float ox = (i % 2 == 0 ? -1f : 1f) * (1.5f + i), oz = (i < 2 ? 1.5f : -2f);
                    Enemy(kind, new Vector3(x + ox, 0f, z + oz), rnd.Next(0, 360), false);
                }
                if (dead)
                {
                    deadEnds++;
                    Interact(deadEnds % 2 == 0 ? "Chest (rich)" : "Chest", PrimitiveType.Cube, new Vector3(x, 0.4f, z + hs - 1.6f), new Vector3(1.2f, 0.8f, 0.8f), false);
                    if (deadEnds == 2) Interact("Mercenary: Isolde of the Ashes", PrimitiveType.Capsule, new Vector3(x + 2.5f, 1f, z - 2f), new Vector3(0.6f, 1f, 0.6f), false);
                    if (deadEnds == 1) Item("Knight's Sigil", PrimitiveType.Cylinder, new Vector3(x - 2f, 0.8f, z + hs - 1.6f), new Vector3(0.5f, 0.04f, 0.5f), mTool);
                }
                else if (rnd.NextDouble() < 0.35) Item(rnd.NextDouble() < 0.5 ? "Health Potion" : "Mana Vial", PrimitiveType.Sphere, new Vector3(x + hs - 1.5f, 0.5f, z + hs - 1.5f), Vector3.one * 0.45f, mPowerUp);
                if (rnd.NextDouble() < 0.3) Trap("Spike Plate", new Vector3(x, 0.03f, z - 1f), new Vector3(2f, 0.06f, 5f));
            }

            // corridors between rooms
            foreach (var l in links)
            {
                var g = Group("Catacomb Corridor", gStructure);
                if (l.Item2 == l.Item4)
                {
                    float z = Z(l.Item2), xa = X(l.Item1) - size[l.Item1, l.Item2] / 2f, xb = X(l.Item3) + size[l.Item3, l.Item4] / 2f;
                    Floor(g, xb, xa, z - 1.5f, z + 1.5f, 0f, mFloor);
                    WallX(g, z - 1.5f, xb, xa, 0, 4f, mMossWall); WallX(g, z + 1.5f, xb, xa, 0, 4f, mMossWall);
                    Ceiling(xb, xa, z - 1.5f, z + 1.5f, 4f);
                }
                else
                {
                    float x = X(l.Item1), za = Z(l.Item2) + size[l.Item1, l.Item2] / 2f, zb = Z(l.Item4) - size[l.Item3, l.Item4] / 2f;
                    Floor(g, x - 1.5f, x + 1.5f, za, zb, 0f, mFloor);
                    WallZ(g, x - 1.5f, za, zb, 0, 4f, mMossWall); WallZ(g, x + 1.5f, za, zb, 0, 4f, mMossWall);
                    Ceiling(x - 1.5f, x + 1.5f, za, zb, 4f);
                }
            }
            // entrance corridor from the guard room's west door
            var ec = Group("Catacomb Entrance", gStructure);
            float ex = X(0) + size[0, 1] / 2f;
            Floor(ec, ex, -6f, 31f, 34f, 0f, mFloor);
            WallX(ec, 31f, ex, -6f, 0, 4f, mWall); WallX(ec, 34f, ex, -6f, 0, 4f, mWall);
            Ceiling(ex, -6f, 31f, 34f, 4f);
            Sign("LOWER CATACOMBS", new Vector3((ex - 6f) / 2f, 3.2f, 32.5f));
        }

        // 2. Guard Room x -6..10 z 26..38, 3. Armory x -2..4 z 38..44
        void BuildGuardRoomAndArmory()
        {
            var a = Group("2 Guard Room", gStructure);
            Floor(a, -6, 10, 26, 38, 0f, mFloor);
            WallX(a, 26f, -6, 10, 0, 5f, mWall, new Vector2(0.5f, 3.5f));
            WallX(a, 38f, -6, 10, 0, 5f, mWall, new Vector2(-0.5f, 2.5f));
            WallZ(a, -6f, 26, 38, 0, 5f, mWall, new Vector2(31f, 34f)); // west door to the Lower Catacombs
            WallZ(a, 10f, 26, 38, 0, 5f, mWall, new Vector2(30.5f, 33.5f));
            Ceiling(-6, 10, 26, 38, 5f);

            Box("Table", gProps, new Vector3(3f, 0.45f, 34f), new Vector3(3f, 0.9f, 1.4f), mWood);
            Box("Bench", gProps, new Vector3(3f, 0.25f, 32.6f), new Vector3(2.6f, 0.5f, 0.5f), mWood);
            Box("Weapon Rack", gProps, new Vector3(-5.6f, 1.2f, 31f), new Vector3(0.4f, 2.4f, 3f), mWood);
            Crate(new Vector3(8.5f, 0f, 27.5f), 1.1f); Crate(new Vector3(8.6f, 1.1f, 27.6f), 0.8f); Barrel(new Vector3(-5f, 0f, 37f));
            Pillar(a, new Vector3(-2f, 0f, 32f), 0.6f, 5f); Pillar(a, new Vector3(6f, 0f, 32f), 0.6f, 5f);
            Torch(new Vector3(-5.7f, 2.8f, 35f), 90f); Torch(new Vector3(9.7f, 2.8f, 36f), 270f); Torch(new Vector3(6f, 2.8f, 26.3f), 0f);

            // lever-operated portcullis on the east door, shown raised
            Interact("Lever (opens east gate)", PrimitiveType.Cube, new Vector3(-5.6f, 1.1f, 34f), new Vector3(0.3f, 1f, 0.3f));
            for (int i = 0; i < 6; i++)
                Interact("Portcullis Bar (raised)", PrimitiveType.Cube, new Vector3(10f, 3.6f, 30.8f + i * 0.5f), new Vector3(0.12f, 1.2f, 0.12f), false);

            Item("Mana Vial", PrimitiveType.Cylinder, new Vector3(8f, 0.5f, 36f), new Vector3(0.35f, 0.25f, 0.35f), mPowerUp);
            Enemy("Husk Sentinel", new Vector3(1f, 0f, 30f), 180f, false);
            Enemy("Husk Sentinel", new Vector3(7f, 0f, 34f), 200f, false);
            Sign("2  GUARD ROOM", new Vector3(2f, 3.8f, 29f));

            var b = Group("3 Armory (optional)", gStructure);
            Floor(b, -2, 4, 38, 44, 0f, mFloor);
            WallX(b, 44f, -2, 4, 0, 4f, mWall);
            WallZ(b, -2f, 38, 44, 0, 4f, mWall);
            WallZ(b, 4f, 38, 44, 0, 4f, mWall);
            Ceiling(-2, 4, 38, 44, 4f);
            Box("Armory Table", gProps, new Vector3(1f, 0.45f, 42.5f), new Vector3(4f, 0.9f, 1.2f), mWood);
            Box("Shield Rack", gProps, new Vector3(-1.7f, 1f, 41f), new Vector3(0.3f, 2f, 2f), mWood);
            Torch(new Vector3(3.7f, 2.6f, 41f), 270f);
            Item("Frost Shard tome", PrimitiveType.Cube, new Vector3(0f, 1.1f, 42.5f), new Vector3(0.5f, 0.15f, 0.4f), mTool);
            Interact("Chest", PrimitiveType.Cube, new Vector3(-1f, 0.4f, 39f), new Vector3(1.2f, 0.8f, 0.8f), false);
            Item("Iron Pauldron", PrimitiveType.Sphere, new Vector3(2f, 1.15f, 42.5f), new Vector3(0.5f, 0.3f, 0.5f), mTool);
            Sign("3  ARMORY", new Vector3(1f, 3.2f, 40f));
        }

        // 4. Collapsed Hall x 10..34 z 29.5..34.5, with a spiked pit at x 19..21.5
        void BuildCollapsedHall()
        {
            var a = Group("4 Collapsed Hall", gStructure);
            Floor(a, 10, 19, 29.5f, 34.5f, 0f, mFloor, 1.7f);
            Floor(a, 21.5f, 34, 29.5f, 34.5f, 0f, mFloor, 1.7f);
            Floor(a, 19, 21.5f, 29.5f, 34.5f, -1.2f, mRubble);
            WallX(a, 29.5f, 10, 34, -1.2f, 4.5f, mWall);
            WallX(a, 34.5f, 10, 34, -1.2f, 4.5f, mMossWall);
            Ceiling(10, 18, 29.5f, 34.5f, 4.5f);
            Ceiling(23, 34, 29.5f, 34.5f, 4.5f); // ceiling caved in over the pit

            for (int i = 0; i < 8; i++)
