        void MakeMaterials()
        {
            mWall = TexMat("StoneBrick", TexBricks(256, 8, 4, new Color(0.46f, 0.43f, 0.4f), 0f, 11), 0.15f);
            mMossWall = TexMat("MossyBrick", TexBricks(256, 8, 4, new Color(0.4f, 0.42f, 0.36f), 0.55f, 23), 0.2f);
            mFloor = TexMat("Flagstone", TexFlagstones(256, 31), 0.2f);
            mRubble = TexMat("RubbleDirt", TexNoise(256, new Color(0.3f, 0.27f, 0.23f), new Color(0.48f, 0.44f, 0.38f), 8, 41), 0.1f);
            mWood = TexMat("WoodPlanks", TexPlanks(256, 53), 0.25f);
            mWater = TexMat("Water", TexNoise(256, new Color(0.05f, 0.2f, 0.24f), new Color(0.12f, 0.38f, 0.42f), 6, 67), 0.9f);
            mMetal = TexMat("DarkIron", TexNoise(128, new Color(0.12f, 0.12f, 0.13f), new Color(0.26f, 0.25f, 0.25f), 16, 71), 0.55f);
            mPillar = TexMat("PillarStone", TexBricks(256, 4, 2, new Color(0.5f, 0.47f, 0.43f), 0.2f, 83), 0.15f);
            mBone = Col("Bone", new Color(0.85f, 0.82f, 0.72f), 0.2f);

            mEnemy = Col("Enemy_Red", new Color(0.85f, 0.1f, 0.1f), 0.2f);
            mBoss = Col("Boss_DarkRed", new Color(0.55f, 0.03f, 0.05f), 0.3f);
            mPowerUp = Col("PowerUp_Green", new Color(0.15f, 0.8f, 0.25f), 0.4f, true);
            mTool = Col("Tool_Blue", new Color(0.15f, 0.4f, 1f), 0.4f, true);
            mTrap = Col("Trap_Yellow", new Color(1f, 0.85f, 0.1f), 0.3f);
            mInteract = Col("Interactable_Purple", new Color(0.6f, 0.25f, 0.9f), 0.4f, true);
            mBoat = Col("Boat_Cyan", new Color(0.2f, 0.9f, 0.95f), 0.3f);
            mFlame = Col("Flame", new Color(1f, 0.55f, 0.15f), 0f, true);
        }

        static Shader LitShader()
        {
            Shader s = null;
            if (GraphicsSettings.currentRenderPipeline != null)
                s = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("HDRP/Lit");
            return s != null ? s : Shader.Find("Standard");
        }

        Material NewOrLoad(string name)
        {
            string path = matDir + "/FV1_" + name + ".mat";
            var m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null) { m = new Material(LitShader()); AssetDatabase.CreateAsset(m, path); }
            else m.shader = LitShader();
            return m;
        }

        Material Col(string name, Color c, float smooth, bool glow = false)
        {
            var m = NewOrLoad(name);
            SetColor(m, c);
            SetSmooth(m, smooth);
            if (glow && m.HasProperty("_EmissionColor"))
            {
                m.EnableKeyword("_EMISSION");
                m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None;
                m.SetColor("_EmissionColor", c * 0.8f);
            }
            EditorUtility.SetDirty(m);
            return m;
        }

        Material TexMat(string name, Texture2D tex, float smooth)
        {
            var m = NewOrLoad(name);
            SetColor(m, Color.white);
            if (m.HasProperty("_BaseMap")) m.SetTexture("_BaseMap", tex);
            if (m.HasProperty("_MainTex")) m.SetTexture("_MainTex", tex);
            SetSmooth(m, smooth);
            EditorUtility.SetDirty(m);
            return m;
        }

        static void SetColor(Material m, Color c)
        {
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
            if (m.HasProperty("_Color")) m.SetColor("_Color", c);
        }

        static void SetSmooth(Material m, float s)
        {
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", s);
            if (m.HasProperty("_Glossiness")) m.SetFloat("_Glossiness", s);
        }

        Texture2D SaveTex(string name, Color[] px, int size)
        {
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, true);
            tex.SetPixels(px);
            tex.Apply();
            string path = texDir + "/FV1_" + name + ".png";
            File.WriteAllBytes(Path.Combine(Directory.GetCurrentDirectory(), path), tex.EncodeToPNG());
            DestroyImmediate(tex);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            imp.wrapMode = TextureWrapMode.Repeat;
            imp.filterMode = FilterMode.Bilinear;
            imp.anisoLevel = 4;
            imp.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        // --- tileable noise ---
        static float Hash(int x, int y, int seed)
        {
            unchecked
            {
                int h = x * 374761393 + y * 668265263 + seed * 982451653;
                h = (h ^ (h >> 13)) * 1274126177;
                h ^= h >> 16;
                return (h & 0x7fffffff) / (float)int.MaxValue;
            }
        }

        static float Noise(float x, float y, int period, int seed)
        {
            int xi = Mathf.FloorToInt(x), yi = Mathf.FloorToInt(y);
            float fx = x - xi, fy = y - yi;
            fx = fx * fx * (3f - 2f * fx); fy = fy * fy * (3f - 2f * fy);
            int x0 = ((xi % period) + period) % period, y0 = ((yi % period) + period) % period;
            int x1 = (x0 + 1) % period, y1 = (y0 + 1) % period;
            float a = Mathf.Lerp(Hash(x0, y0, seed), Hash(x1, y0, seed), fx);
            float b = Mathf.Lerp(Hash(x0, y1, seed), Hash(x1, y1, seed), fx);
            return Mathf.Lerp(a, b, fy);
        }

        static float Fbm(float u, float v, int basePeriod, int seed)
        {
            float sum = 0f, amp = 0.5f, norm = 0f;
            int p = basePeriod;
            for (int o = 0; o < 4; o++)
            {
                sum += Noise(u * p, v * p, p, seed + o * 17) * amp;
                norm += amp; amp *= 0.5f; p *= 2;
            }
            return sum / norm;
        }

        Texture2D TexNoise(int size, Color dark, Color light, int period, int seed)
        {
            var px = new Color[size * size];
            for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                {
                    float n = Fbm(x / (float)size, y / (float)size, period, seed);
                    px[y * size + x] = Color.Lerp(dark, light, Mathf.SmoothStep(0.2f, 0.8f, n));
                }
            return SaveTex("Noise_" + seed, px, size);
        }

        Texture2D TexBricks(int size, int rows, int cols, Color baseCol, float moss, int seed)
        {
            var px = new Color[size * size];
            Color mortar = baseCol * 0.45f; mortar.a = 1f;
            Color mossCol = new Color(0.22f, 0.32f, 0.16f);
            for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                {
                    float u = x / (float)size, v = y / (float)size;
                    float rv = v * rows; int row = Mathf.FloorToInt(rv);
                    float cu = u * cols + (row % 2) * 0.5f; int col = ((Mathf.FloorToInt(cu) % cols) + cols) % cols;
                    float fu = cu - Mathf.Floor(cu), fv = rv - row;
                    float edge = Mathf.Min(Mathf.Min(fu, 1f - fu) * 2f, Mathf.Min(fv, 1f - fv) * 1.2f);
                    float grain = Fbm(u, v, 16, seed);
                    Color c;
                    if (edge < 0.06f) c = mortar * (0.8f + 0.4f * grain);
                    else
                    {
                        float tone = 0.78f + 0.4f * Hash(col, row, seed);
                        c = baseCol * tone * (0.8f + 0.35f * grain);
                        if (edge < 0.15f) c *= 0.85f;
                    }
                    if (moss > 0f)
                    {
                        float m = Fbm(u, v, 4, seed + 5) * (1f - v * 0.6f);
                        if (m > 1f - moss * 0.6f) c = Color.Lerp(c, mossCol, Mathf.Clamp01((m - (1f - moss * 0.6f)) * 6f));
                    }
                    c.a = 1f;
                    px[y * size + x] = c;
                }
            return SaveTex("Bricks_" + seed, px, size);
        }

        Texture2D TexFlagstones(int size, int seed)
        {
            var px = new Color[size * size];
            Color baseCol = new Color(0.42f, 0.4f, 0.37f);
            const int rows = 4, cols = 3;
            for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                {
                    float u = x / (float)size, v = y / (float)size;
                    float rv = v * rows; int row = Mathf.FloorToInt(rv);
                    float cu = u * cols + Hash(row, 0, seed) * 0.9f; int col = ((Mathf.FloorToInt(cu) % cols) + cols) % cols;
                    float fu = cu - Mathf.Floor(cu), fv = rv - row;
                    float edge = Mathf.Min(Mathf.Min(fu, 1f - fu) * 1.5f, Mathf.Min(fv, 1f - fv));
                    float grain = Fbm(u, v, 12, seed);
                    Color c = edge < 0.04f
                        ? baseCol * 0.35f
                        : baseCol * (0.75f + 0.45f * Hash(col, row, seed + 3)) * (0.75f + 0.4f * grain) * (edge < 0.1f ? 0.85f : 1f);
                    float crack = Mathf.Abs(Noise(u * 24f, v * 24f, 24, seed + 9) - 0.5f);
                    if (crack < 0.012f) c *= 0.6f;
                    c.a = 1f;
                    px[y * size + x] = c;
                }
            return SaveTex("Flagstone_" + seed, px, size);
        }

        Texture2D TexPlanks(int size, int seed)
        {
            var px = new Color[size * size];
            Color baseCol = new Color(0.42f, 0.28f, 0.16f);
            const int planks = 5;
            for (int y = 0; y < size; y++)
                for (int x = 0; x < size; x++)
                {
                    float u = x / (float)size, v = y / (float)size;
                    float pu = u * planks; int plank = Mathf.FloorToInt(pu); float fu = pu - plank;
                    float seam = Hash(plank, 1, seed);
                    float fvs = Mathf.Repeat(v + seam, 1f);
                    float grain = Noise(u * 64f, v * 4f, 64, seed) * 0.6f + Noise(u * 128f, v * 8f, 128, seed + 1) * 0.4f;
                    Color c = baseCol * (0.75f + 0.35f * Hash(plank, 2, seed)) * (0.8f + 0.35f * grain);
                    if (fu < 0.03f || fu > 0.97f || fvs < 0.008f) c *= 0.4f;
                    c.a = 1f;
                    px[y * size + x] = c;
                }
            return SaveTex("Planks_" + seed, px, size);
        }

        // =====================================================================================

        static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            string[] parts = path.Split('/');
            string current = parts[0];
            for (int i = 1; i < parts.Length; i++)
            {
                string next = current + "/" + parts[i];
                if (!AssetDatabase.IsValidFolder(next)) AssetDatabase.CreateFolder(current, parts[i]);
                current = next;
            }
        }

        static void AddToBuildSettings(string path)
        {
            var scenes = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            if (scenes.Exists(s => s.path == path)) return;
            scenes.Add(new EditorBuildSettingsScene(path, true));
            EditorBuildSettings.scenes = scenes.ToArray();
        }
    }
